/// <see cref="ConfigurableItem"/> implementation backed by a <see cref="PropertyInfo"/>.
/// </summary>
internal class ConfigurableProperty : ConfigurableItem
{
    /// <summary>The reflected property this item wraps.</summary>
    public required PropertyInfo Property { get; init; }
    public override Type FieldType => Property.PropertyType;
    public override string FieldName => Property.Name;
    public override ConfigurableAttribute FieldAttribute => Property.GetCustomAttribute<ConfigurableAttribute>()!;
    public override object? GetValue(object? instance)
    {
        return Property.GetValue(instance);
    }
    public override void SetValue(object? instance, object? value)
    {
        Property.SetValue(instance, value);
    }
    public override bool IsStatic => (Property.GetMethod ?? Property.SetMethod)?.IsStatic ?? false;
}

/// <summary>
/// This wraps a ConfigurableItem and a instance (null for static fields, not null for instance fields) into a value proxy that can be used for UI editing and binding. It also allows attaching an IEditorTrait for rendering and parsing the value in a generic editor.
/// </summary>
public class  ConfigurableValue: IValueProxy
{

    ConfigurableItem m_item;
    object? m_instance = null; // null for static members, or the target object for instance members
    /// <summary>
    /// Construct the proxy for a ConfigurableItem and its target instance (or null for static members). The DisplayName and HelpContent are taken from the ConfigurableAttribute of the item. The Value property gets/sets the value of the underlying field or property on the target instance (or statically if instance is null) with appropriate type conversion. The EditorTrait can be set to provide editor-specific behavior for this value.
    /// </summary>
    /// <param name="item"></param>
    /// <param name="instance"></param>
    public ConfigurableValue(ConfigurableItem item, object? instance)
    {
        m_item = item;
        m_instance = instance;
    }
    /// <inheritdoc/>
    public required string Displayname { get; init; }

    /// <inheritdoc/>
    public required string HelpContent { get; init; }

    /// <summary>
    /// get and set the value via the ConfigurableItem and the (optional) instance. 
    /// </summary>
    public object? Value { 
        get => m_item.GetValue(m_instance); 
        set => m_item.SetValue(m_instance, value);
    }

    Type IValueProxy.ValueType => m_item.FieldType; 

    /// <inheritdoc/>   
    public IEditorTrait? EditorTrait { get; set;  }
}

/// <summary>
/// Discovers and binds configuration values to fields and properties marked with
/// <see cref="ConfigurableAttribute"/> across all loaded assemblies.
/// </summary>
/// <remarks>
/// <para>
/// At construction the binder scans every loaded assembly for configurable <b>static</b>
/// members and populates them from the supplied <see cref="IConfiguration"/> source.
/// It also monitors for newly loaded assemblies and applies configuration to them
/// automatically. <b>Instance</b> members are populated on demand via
/// <see cref="ConfigurableExtensions.BindConfigurable{T}(IConfiguration)"/>.
/// </para>
/// <para>
/// Discovery is provided by the <see cref="GetConfigurableItems()"/> family of methods,
/// which enumerate <see cref="ConfigurableItem"/> descriptors for every marked member.
/// These can be used for diagnostics and configuration UI pages.
/// </para>
/// <para>
/// <b>Thread Safety:</b> The binder tracks processed assemblies to prevent duplicate loading.
/// While the tracking mechanism is thread-safe, concurrent access to the static fields
/// being configured is not protected. Ensure the binder is created during application
/// startup before multi-threaded access begins.
/// </para>
/// <para>
/// <b>Lifecycle:</b> The binder should be disposed when no longer needed (typically at
/// application shutdown) to unregister the assembly load event handler.
/// </para>
/// </remarks>
/// <example>
/// <code>
/// // During application startup
/// var config = new ConfigurationBuilder()
///     .AddJsonFile("appsettings.json")
///     .Build();
/// 
/// using var binder = new ConfigurableBinder(config);
/// // All configurable static fields in loaded assemblies are now initialized.
/// // Newly loaded assemblies will also have their static fields configured automatically.
/// 
/// // Instance members are bound explicitly:
/// var renderer = new BohrlochRenderer();
/// config.BindConfigurable(renderer);
/// </code>
/// </example>
public class ConfigurableBinder : IDisposable
{
    /// <summary>
    /// Enumerates all <see cref="ConfigurableItem"/> instances across every loaded assembly
    /// in the current <see cref="AppDomain"/>.
    /// </summary>
    public static IEnumerable<ConfigurableItem> GetConfigurableItems()
    {
        return AppDomain.CurrentDomain.GetAssemblies().SelectMany(GetConfigurableItems);
    }

    /// <summary>
    /// Enumerates all <see cref="ConfigurableItem"/> instances in <paramref name="assembly"/>.
    /// Returns an empty sequence if the assembly has no <see cref="ConfigurableAttribute"/>.
    /// </summary>
    public static IEnumerable<ConfigurableItem> GetConfigurableItems(Assembly assembly)
    {
        var assAtt = assembly.GetCustomAttribute<ConfigurableAttribute>();
        if (assAtt == null) return Enumerable.Empty<ConfigurableItem>();
        return assembly.GetTypes().SelectMany(GetConfigurableItems);
    }

    static readonly BindingFlags s_defaultBindingFlags = BindingFlags.Public | BindingFlags.NonPublic | BindingFlags.Static | BindingFlags.Instance;

    /// <summary>
    /// Enumerates all <see cref="ConfigurableItem"/> instances declared on <paramref name="type"/>.
    /// Returns nothing if the type has no <see cref="ConfigurableAttribute"/>.
    /// Both static and instance members (fields and properties) are included.
    /// </summary>
    public static IEnumerable<ConfigurableItem> GetConfigurableItems(Type type)
    {
        var typeAtt = type.GetCustomAttribute<ConfigurableAttribute>();
        if (typeAtt == null) yield break;
        var assembly = type.Assembly;
        var fields = type.GetFields(s_defaultBindingFlags);
        foreach (var field in fields)
        {
            var fieldAtt = field.GetCustomAttribute<ConfigurableAttribute>();
            if (fieldAtt == null) continue;
            yield return new ConfigurableField { Assembly = assembly, DeclaringClassType = type, Field = field };
        }
        var properties = type.GetProperties(s_defaultBindingFlags);
        foreach (var property in properties)
        {
            var propAtt = property.GetCustomAttribute<ConfigurableAttribute>();
            if (propAtt == null) continue;
            yield return new ConfigurableProperty { Assembly = assembly, DeclaringClassType = type, Property = property };
        }
    }
